-- Seed finding length budgets: the readonly setup-analyzer default template
-- (steps JSON) is missing the per-step length-budget guidance that the live
-- nrworkflow/feature/plan agent_definitions row already carries (added
-- out-of-band). Bring default_templates.steps up to that same text so newly
-- seeded tiered projects are born with capped findings, mirroring 000205's
-- readonly guard pattern.

UPDATE default_templates SET steps = '[{"step_id":"requirements-risks","title":"Requirements \u0026 risks","instruction":"## Step: Requirements \u0026 risks\n\nRead the ticket title, description, and any user instructions. Identify assumptions, dependencies, and ambiguities in the requirement. If something is ambiguous, choose the most reasonable interpretation and record it as part of your risk notes.\n\nDo not explore the codebase yet -- this step is about understanding the requirement itself.\n\nRecord your findings:\n\n- `plan_risks` (nonempty_text): assumptions, dependencies, ambiguities, and the interpretation you chose for anything unclear. If there are no material risks, record why the requirement is unambiguous.\n\nKeep `plan_risks` under ~20 lines.\n\nThen call `complete_step` with the current step_id and revision.\n","required_findings":[{"key":"plan_risks","schema":"nonempty_text"}],"rotation_allowed":true},{"step_id":"explore-backend","title":"Backend exploration","instruction":"## Step: Backend exploration\n\nExplore the codebase read-only for the backend side of this ticket. Use `Glob`, `Grep`, and `Read` -- do not modify files or write code.\n\n- Find backend files that need changes, and any new backend files needed.\n- Identify existing backend patterns and conventions to follow.\n- Check existing backend test coverage and note what new tests will be needed.\n- Note FE/BE integration boundaries (API contracts, DTOs, routes, schemas).\n\nIf the backend side is not impacted by this ticket, do not skip this step -- instead record the skip explicitly: `be_files_to_modify` and `be_files_to_create` as `[]`, `be_plan_summary`/`be_patterns_to_follow`/`be_testing_notes` as \"none -- \u003creason\u003e\", and `be_implementation_steps` as two numbered lines stating the backend side is not impacted and why (for example \"1. Backend is not impacted by this ticket.\" / \"2. \u003creason\u003e.\"). Actually skipping the backend side happens later, in the cross-check step, via the `workflow_skip` tool -- not here.\n\nRecord your findings:\n\n- `be_plan_summary` (nonempty_text): 2-3 sentences summarizing the backend plan.\n- `be_files_to_modify` (json_array_path_change): array of objects with a `path` and a `change` description.\n- `be_files_to_create` (json_array_path_change): array of objects with a `path` and a `purpose` description.\n- `be_implementation_steps` (ordered_lines): ordered steps, one per line, formatted \"1. ...\", \"2. ...\".\n- `be_patterns_to_follow` (nonempty_text): conventions to follow, with file/line evidence where useful.\n- `be_testing_notes` (nonempty_text): existing tests, patterns, and the new cases needed.\n\nPaths in `be_files_to_modify`/`be_files_to_create` are resolved against the worktree; a path that cannot be uniquely resolved comes back as a non-fatal flag, not a rejection -- this is expected for files that do not exist yet (e.g. `be_files_to_create`).\n\n**Findings are streamed -- keep them tight:** `*_implementation_steps` at most 12 numbered lines; `*_patterns_to_follow` at most 15 short bullets; `*_testing_notes` at most 10 lines; each `change`/`purpose` description one sentence. Do not paste file contents or code excerpts into findings -- reference `path:line` instead.\n\nThen call `complete_step` with the current step_id and revision.\n","required_findings":[{"key":"be_plan_summary","schema":"nonempty_text"},{"key":"be_files_to_modify","schema":"json_array_path_change"},{"key":"be_files_to_create","schema":"json_array_path_change"},{"key":"be_implementation_steps","schema":"ordered_lines"},{"key":"be_patterns_to_follow","schema":"nonempty_text"},{"key":"be_testing_notes","schema":"nonempty_text"}],"rotation_allowed":true},{"step_id":"explore-frontend","title":"Frontend exploration","instruction":"## Step: Frontend exploration\n\nExplore the codebase read-only for the frontend side of this ticket. Use `Glob`, `Grep`, and `Read` -- do not modify files or write code.\n\n- Find frontend files that need changes, and any new frontend files needed.\n- Identify existing frontend patterns and conventions to follow.\n- Check existing frontend test coverage and note what new tests will be needed.\n- Note FE/BE integration boundaries (API contracts, DTOs, routes, schemas).\n\nIf the frontend side is not impacted by this ticket, do not skip this step -- instead record the skip explicitly: `fe_files_to_modify` and `fe_files_to_create` as `[]`, `fe_plan_summary`/`fe_patterns_to_follow`/`fe_testing_notes` as \"none -- \u003creason\u003e\", and `fe_implementation_steps` as two numbered lines stating the frontend side is not impacted and why (for example \"1. Frontend is not impacted by this ticket.\" / \"2. \u003creason\u003e.\"). Actually skipping the frontend side happens later, in the cross-check step, via the `workflow_skip` tool -- not here.\n\nRecord your findings:\n\n- `fe_plan_summary` (nonempty_text): 2-3 sentences summarizing the frontend plan.\n- `fe_files_to_modify` (json_array_path_change): array of objects with a `path` and a `change` description.\n- `fe_files_to_create` (json_array_path_change): array of objects with a `path` and a `purpose` description.\n- `fe_implementation_steps` (ordered_lines): ordered steps, one per line, formatted \"1. ...\", \"2. ...\".\n- `fe_patterns_to_follow` (nonempty_text): conventions to follow, with file/line evidence where useful.\n- `fe_testing_notes` (nonempty_text): existing tests, patterns, and the new cases needed.\n\nPaths in `fe_files_to_modify`/`fe_files_to_create` are resolved against the worktree; a path that cannot be uniquely resolved comes back as a non-fatal flag, not a rejection -- this is expected for files that do not exist yet (e.g. `fe_files_to_create`).\n\n**Findings are streamed -- keep them tight:** `*_implementation_steps` at most 12 numbered lines; `*_patterns_to_follow` at most 15 short bullets; `*_testing_notes` at most 10 lines; each `change`/`purpose` description one sentence. Do not paste file contents or code excerpts into findings -- reference `path:line` instead.\n\nThen call `complete_step` with the current step_id and revision.\n","required_findings":[{"key":"fe_plan_summary","schema":"nonempty_text"},{"key":"fe_files_to_modify","schema":"json_array_path_change"},{"key":"fe_files_to_create","schema":"json_array_path_change"},{"key":"fe_implementation_steps","schema":"ordered_lines"},{"key":"fe_patterns_to_follow","schema":"nonempty_text"},{"key":"fe_testing_notes","schema":"nonempty_text"}],"rotation_allowed":true},{"step_id":"cross-check","title":"Cross-side check \u0026 completeness","instruction":"## Step: Cross-side check \u0026 completeness\n\nReview the backend and frontend findings you recorded in the previous two steps together.\n\n- File ownership is exclusive: every file must appear in at most ONE side''s `*_files_to_modify`/`*_files_to_create` lists -- backend and frontend implementors run in parallel in the same worktree. If a file is genuinely needed by both sides (shared docs, generated types), assign it to the backend side and note the dependency in `fe_patterns_to_follow`.\n- If the backend or frontend side of the ticket is not needed, mark it with the `workflow_skip` tool now (one call per side): backend not needed -\u003e `workflow_skip` with `{\"tag\":\"be\"}`; frontend not needed -\u003e `workflow_skip` with `{\"tag\":\"fe\"}`.\n\nRecord your findings:\n\n- `plan_cross_check` (nonempty_text): confirmation that file ownership is exclusive across the two sides (or how you resolved any conflict), and which sides, if any, you skipped and why.\n\nOnce `complete_step` accepts this step, the plan is done -- you record nothing further and call `agent_finished`.\n","required_findings":[{"key":"plan_cross_check","schema":"nonempty_text"}],"path_overlap":{"left":["be_files_to_modify","be_files_to_create"],"right":["fe_files_to_modify","fe_files_to_create"]}}]' , updated_at = '2026-07-24T00:00:00Z' WHERE id = 'setup-analyzer' AND readonly = 1;

-- Copy onto the live nrworkflow/feature/plan def too, in case any
-- environment has 000205 applied but not the out-of-band edit; guarded
-- idempotent on prompt_mode='stepwise' (set by 000205) so unrelated plan
-- defs are untouched.
UPDATE agent_definitions
SET steps = (SELECT steps FROM default_templates WHERE id = 'setup-analyzer'),
    updated_at = '2026-07-24T00:00:00Z'
WHERE project_id = 'nrworkflow' AND workflow_id = 'feature' AND id = 'plan' AND prompt_mode = 'stepwise';
